export enum UserRole {
  SUPERADMIN = 'SUPERADMIN', // Auditoría y Control Maestro
  ADMIN = 'ADMIN',           // Gestión Central: Recepción y Derivación
  HEAD = 'HEAD',            // Jefatura de Área: Gestión de Recursos y Asignación
  ANALYST = 'ANALYST'       // Cuerpo Técnico: Ejecución y Resolución
}

export enum Area {
  CONTABILIDAD = 'Contabilidad',
  RRHH = 'RRHH',
  ACREDITACION = 'Acreditación',
  FINANZAS = 'Finanzas'
}

export enum Status {
  RECIBIDO = 'Recibido',      // Bandeja de Entrada Central (Admin)
  DERIVACION = 'En Derivación', // Asignado a un Área (Jefe de Área)
  EJECUCION = 'En Ejecución',   // En trabajo activo por un Analista
  FINALIZADO = 'Finalizado'     // Requerimiento resuelto y auditado
}

export enum Priority {
  HIGH = 'Alta',
  MEDIUM = 'Media',
  LOW = 'Baja'
}

export type UserStatus = 'ACTIVE' | 'INACTIVE';
export type ViewMode = 'work' | 'superadmin';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  area?: Area; 
  password?: string;
  status?: UserStatus;
  joinedAt?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  actor: string;
  role: UserRole;
}

export interface RequestCard {
  id: string;
  title: string;
  detail: string;
  requester: string;
  area: Area;
  status: Status;
  priority: Priority;
  responsibleHead: string; 
  assignedAnalyst?: string; 
  logs: LogEntry[];
  createdAt: string;
  lastUpdated: string;
  finishedAt?: string;
  isReturned?: boolean; 
}

/**
 * Matriz de Transición de Estados (Ingeniería de Procesos)
 * Define las reglas de negocio para el flujo de trabajo SISREQ.
 */
export interface TransitionRule {
  from: Status;
  to: Status;
  allowedRoles: UserRole[];
  requiresAnalyst?: boolean;
  checkAreaJurisdiction?: boolean;
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, ViewMode, TransitionRule } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  activeRole: UserRole | null;
  viewMode: ViewMode;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  setViewMode: (mode: ViewMode) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

// MOTOR DE REGLAS DE NEGOCIO (Workflow Engine Matrix)
const WORKFLOW_MATRIX: TransitionRule[] = [
  // De Recibido a Derivación (Admin/SuperAdmin)
  { from: Status.RECIBIDO, to: Status.DERIVACION, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  // De Derivación a Ejecución (Jefe de Área, requiere analista)
  { from: Status.DERIVACION, to: Status.EJECUCION, allowedRoles: [UserRole.HEAD, UserRole.SUPERADMIN], requiresAnalyst: true, checkAreaJurisdiction: true },
  // De Ejecución a Finalizado (Analista o Jefe)
  { from: Status.EJECUCION, to: Status.FINALIZADO, allowedRoles: [UserRole.ANALYST, UserRole.HEAD, UserRole.ADMIN, UserRole.SUPERADMIN], checkAreaJurisdiction: true },
  // De Cualquier estado a Finalizado (Solo Admin/SuperAdmin por excepción)
  { from: Status.RECIBIDO, to: Status.FINALIZADO, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.DERIVACION, to: Status.FINALIZADO, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  // Re-apertura (Solo SuperAdmin)
  { from: Status.FINALIZADO, to: Status.RECIBIDO, allowedRoles: [UserRole.SUPERADMIN] }
];

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
      } catch (error) {
        console.error("CRITICAL: SISREQ Storage Layer Failure", error);
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    setGlobalFilterArea(user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN ? 'ALL' : (user.area as Area));
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setViewMode('work');
  };

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;

    // Visibilidad por área para perfiles operativos
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;
    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no válida.' };
    if (req.status === target) return { allowed: true };

    // Búsqueda en matriz de reglas
    const rule = WORKFLOW_MATRIX.find(r => r.from === req.status && r.to === target);

    if (!rule) {
        // Casos especiales como devoluciones no definidos en matriz positiva
        if (target === Status.RECIBIDO && req.status !== Status.FINALIZADO) {
            if ([UserRole.ADMIN, UserRole.SUPERADMIN, UserRole.HEAD].includes(activeRole)) return { allowed: true };
            return { allowed: false, reason: 'No tiene privilegios para retornar el ticket a central.' };
        }
        return { allowed: false, reason: 'Transición de estado no permitida por el flujo de trabajo institucional.' };
    }

    // Validación de Rol
    if (!rule.allowedRoles.includes(activeRole)) {
        return { allowed: false, reason: `El rol ${activeRole} no tiene facultades para esta acción.` };
    }

    // Validación de Jurisdicción
    if (rule.checkAreaJurisdiction && activeRole !== UserRole.SUPERADMIN && activeRole !== UserRole.ADMIN) {
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción ajena al área de adscripción.' };
    }

    // Validación de Requisitos Técnicos
    if (rule.requiresAnalyst && !req.assignedAnalyst) {
        return { allowed: false, reason: 'El requerimiento debe tener un analista asignado para iniciar ejecución.' };
    }

    return { allowed: true };
  }, [currentUser, activeRole]);

  // OPERACIONES ATÓMICAS (Persistencia + Estado)
  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title: title.trim(),
      detail: detail.trim(),
      area,
      status: Status.RECIBIDO,
      priority,
      requester: requester.trim(),
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro formal en sistema central',
        actor: currentUser?.name || 'Sistema',
        role: activeRole || UserRole.ADMIN
      }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    setRequests(prev => {
        const reqIndex = prev.findIndex(r => r.id === id);
        if (reqIndex === -1 || !currentUser || !activeRole) return prev;

        const req = prev[reqIndex];
        const validation = canUserTransition(req, newStatus);
        if (!validation.allowed) throw new Error(validation.reason);

        const now = new Date().toISOString();
        const isReturning = newStatus === Status.RECIBIDO;

        const updated: RequestCard = {
          ...req,
          status: newStatus,
          lastUpdated: now,
          finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
          assignedAnalyst: isReturning ? undefined : req.assignedAnalyst,
          isReturned: isReturning ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
          logs: [...req.logs, {
            id: genId('LOG'),
            timestamp: now,
            message: `SISTEMA: Cambio de fase a [${newStatus.toUpperCase()}]`,
            actor: currentUser.name,
            role: activeRole
          }]
        };

        db.saveRequest(updated); // Side effect asíncrono controlado
        const newRequests = [...prev];
        newRequests[reqIndex] = updated;
        return newRequests;
    });
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN: ${reason}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN TÉCNICA: ${analystName}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: message.trim(),
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title: title.trim(),
      detail: detail.trim(),
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: 'MODIFICACIÓN: Actualización de metadatos del expediente',
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = {
      id: genId('U'),
      name: name.trim(),
      email: email.trim(),
      role,
      area,
      password: pass,
      status: 'ACTIVE',
      joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, setViewMode, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

import { RequestCard, User } from '../types';
import { INITIAL_USERS, INITIAL_REQUESTS } from '../constants';

const DB_NAME = 'SISREQ_DATABASE';
const DB_VERSION = 1;
const STORE_REQUESTS = 'requests';
const STORE_USERS = 'users';

class DatabaseService {
    private db: IDBDatabase | null = null;

    public async init(): Promise<void> {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(DB_NAME, DB_VERSION);
            request.onerror = () => {
                console.error("IndexedDB error:", request.error);
                reject(request.error);
            };
            request.onupgradeneeded = (event) => {
                const db = (event.target as IDBOpenDBRequest).result;
                if (!db.objectStoreNames.contains(STORE_REQUESTS)) db.createObjectStore(STORE_REQUESTS, { keyPath: 'id' });
                if (!db.objectStoreNames.contains(STORE_USERS)) db.createObjectStore(STORE_USERS, { keyPath: 'id' });
            };
            request.onsuccess = async (event) => {
                this.db = (event.target as IDBOpenDBRequest).result;
                await this.seedData();
                resolve();
            };
        });
    }

    private async seedData() {
        if (!this.db) return;
        const userCount = await this.count(STORE_USERS);
        if (userCount === 0) {
            const tx = this.db.transaction(STORE_USERS, 'readwrite');
            const store = tx.objectStore(STORE_USERS);
            INITIAL_USERS.forEach(user => store.put(user));
            await new Promise((res) => { tx.oncomplete = res; });
        }
        const reqCount = await this.count(STORE_REQUESTS);
        if (reqCount === 0) {
            const tx = this.db.transaction(STORE_REQUESTS, 'readwrite');
            const store = tx.objectStore(STORE_REQUESTS);
            INITIAL_REQUESTS.forEach(req => store.put(req));
            await new Promise((res) => { tx.oncomplete = res; });
        }
    }

    private count(storeName: string): Promise<number> {
        return new Promise((resolve, reject) => {
            if (!this.db) return reject("DB no inicializada.");
            const tx = this.db.transaction(storeName, 'readonly');
            const store = tx.objectStore(storeName);
            const request = store.count();
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
    }

    public async getAll<T>(storeName: string): Promise<T[]> {
        return new Promise((resolve, reject) => {
            if (!this.db) return reject("DB no inicializada.");
            const tx = this.db.transaction(storeName, 'readonly');
            const store = tx.objectStore(storeName);
            const request = store.getAll();
            request.onsuccess = () => resolve(request.result || []);
            request.onerror = () => reject(request.error);
        });
    }

    public async save<T>(storeName: string, item: T): Promise<void> {
        return new Promise((resolve, reject) => {
            if (!this.db) return reject("DB no inicializada.");
            const tx = this.db.transaction(storeName, 'readwrite');
            const store = tx.objectStore(storeName);
            const request = store.put(item);

            tx.oncomplete = () => resolve();
            tx.onerror = () => {
                console.error(`Error saving to ${storeName}:`, tx.error);
                reject(tx.error);
            };
            request.onerror = () => reject(request.error);
        });
    }

    public async delete(storeName: string, id: string): Promise<void> {
        return new Promise((resolve, reject) => {
            if (!this.db) return reject("DB no inicializada.");
            const tx = this.db.transaction(storeName, 'readwrite');
            const store = tx.objectStore(storeName);
            const request = store.delete(id);
            request.onsuccess = () => resolve();
            request.onerror = () => reject(request.error);
        });
    }

    public async getRequests(): Promise<RequestCard[]> { return this.getAll<RequestCard>(STORE_REQUESTS); }
    public async saveRequest(req: RequestCard): Promise<void> { return this.save(STORE_REQUESTS, req); }
    public async deleteRequest(id: string): Promise<void> { return this.delete(STORE_REQUESTS, id); }
    public async getUsers(): Promise<User[]> { return this.getAll<User>(STORE_USERS); }
    public async saveUser(user: User): Promise<void> { return this.save(STORE_USERS, user); }
}

export const db = new DatabaseService();

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, ViewMode, TransitionRule } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  activeRole: UserRole | null;
  viewMode: ViewMode;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  switchHybridRole: () => void;
  setViewMode: (mode: ViewMode) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
  isActionable: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

const WORKFLOW_MATRIX: TransitionRule[] = [
  { from: Status.RECIBIDO, to: Status.DERIVACION, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.DERIVACION, to: Status.EJECUCION, allowedRoles: [UserRole.HEAD, UserRole.SUPERADMIN], requiresAnalyst: true, checkAreaJurisdiction: true },
  { from: Status.EJECUCION, to: Status.FINALIZADO, allowedRoles: [UserRole.ANALYST, UserRole.HEAD, UserRole.ADMIN, UserRole.SUPERADMIN], checkAreaJurisdiction: true },
  { from: Status.RECIBIDO, to: Status.FINALIZADO, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.DERIVACION, to: Status.FINALIZADO, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.FINALIZADO, to: Status.RECIBIDO, allowedRoles: [UserRole.SUPERADMIN] }
];

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
      } catch (error) {
        console.error("FATAL: Storage Layer Failure", error);
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    setGlobalFilterArea(user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN ? 'ALL' : (user.area as Area));
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setViewMode('work');
  };

  const switchHybridRole = () => {
    if (!currentUser || currentUser.role !== UserRole.ADMIN || !currentUser.area) return;

    if (activeRole === UserRole.ADMIN) {
        setActiveRole(UserRole.HEAD);
        setGlobalFilterArea(currentUser.area as Area);
    } else {
        setActiveRole(UserRole.ADMIN);
        setGlobalFilterArea('ALL');
    }
  };

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;
    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'No session' };
    if (req.status === target) return { allowed: true };

    const rule = WORKFLOW_MATRIX.find(r => r.from === req.status && r.to === target);

    if (!rule) {
        if (target === Status.RECIBIDO && req.status !== Status.FINALIZADO) {
            const hasPower = [UserRole.ADMIN, UserRole.SUPERADMIN, UserRole.HEAD].includes(activeRole);
            return hasPower ? { allowed: true } : { allowed: false, reason: 'Privilegios insuficientes para retorno' };
        }
        return { allowed: false, reason: 'Fase no permitida' };
    }

    if (!rule.allowedRoles.includes(activeRole)) {
        return { allowed: false, reason: `Rol ${activeRole} no autorizado` };
    }

    if (rule.checkAreaJurisdiction && ![UserRole.SUPERADMIN, UserRole.ADMIN].includes(activeRole)) {
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Fuera de jurisdicción' };
    }

    if (rule.requiresAnalyst && !req.assignedAnalyst) {
        return { allowed: false, reason: 'Requiere analista asignado' };
    }

    return { allowed: true };
  }, [currentUser, activeRole]);

  const isActionable = useCallback((req: RequestCard): boolean => {
    if (activeRole === UserRole.SUPERADMIN) return true;

    // Un ticket es accionable (arrastrable) si el usuario actual tiene al menos una transición válida disponible
    const possibleTargets = Object.values(Status).filter(s => s !== req.status);
    return possibleTargets.some(target => canUserTransition(req, target).allowed);
  }, [activeRole, canUserTransition]);

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title: title.trim(),
      detail: detail.trim(),
      area,
      status: Status.RECIBIDO,
      priority,
      requester: requester.trim(),
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro oficial en sistema',
        actor: currentUser?.name || 'Sistema',
        role: activeRole || UserRole.ADMIN
      }]
    };
    try {
        await db.saveRequest(newReq);
        setRequests(prev => [newReq, ...prev]);
    } catch (e) {
        console.error("Error persisting request", e);
        throw e;
    }
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const validation = canUserTransition(req, newStatus);
    if (!validation.allowed) throw new Error(validation.reason);

    const now = new Date().toISOString();
    const isReturning = newStatus === Status.RECIBIDO;

    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      assignedAnalyst: isReturning ? undefined : req.assignedAnalyst,
      isReturned: isReturning ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `WORKFLOW: Transición a ${newStatus}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN: ${reason}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN: ${analystName}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: message.trim(),
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title: title.trim(),
      detail: detail.trim(),
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: 'EDICIÓN: Actualización de metadatos',
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = {
      id: genId('U'),
      name: name.trim(),
      email: email.trim(),
      role,
      area,
      password: pass,
      status: 'ACTIVE',
      joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, switchHybridRole, setViewMode, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest, isActionable
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

