import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { PRIORITY_STYLES } from '../constants';
import { User as UserIcon, GripVertical, MapPin, ChevronUp, ChevronDown, Clock, Hash, Building2, AlertCircle } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { setSelectedRequestId, isActionable } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  const draggable = isActionable(data);

  const handleDragStart = (e: React.DragEvent) => {
    if (!draggable) {
        e.preventDefault();
        return;
    }
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';

    const dragGhost = e.currentTarget as HTMLElement;
    dragGhost.style.opacity = '0.4';
    setTimeout(() => {
        if (dragGhost) dragGhost.style.opacity = '1';
    }, 0);
  };

  const handleCardClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedRequestId(data.id);
  };

  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-indigo-500';
        case Status.DERIVACION: return 'border-orange-500';
        case Status.EJECUCION: return 'border-amber-500';
        case Status.FINALIZADO: return 'border-emerald-500';
        default: return 'border-slate-300';
    }
  };

  return (
    <div 
        draggable={draggable}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-2xl relative group animate-in fade-in slide-in-from-bottom-2 duration-300
            transition-all duration-300 ease-out
            shadow-[0_4px_20px_-10px_rgba(0,0,0,0.1)] hover:shadow-[0_20px_40px_-15px_rgba(0,0,0,0.15)]
            border border-slate-100
            border-l-[6px]
            cursor-pointer flex flex-col
            ${getAccentColor(data.status)}
            ${draggable ? 'hover:bg-indigo-50/10 active:scale-[0.98]' : 'cursor-default'}
            ${isMinimized ? 'h-[64px] py-3 px-6' : 'min-h-[190px] p-6'}
        `}
    >
      <div className={`flex justify-between items-center shrink-0 ${isMinimized ? '' : 'mb-4'}`}>
        <div className="flex items-center gap-3">
            {draggable && !isMinimized && (
                <div onMouseDown={(e) => e.stopPropagation()} className="p-1 -ml-2 text-slate-200 group-hover:text-indigo-400 cursor-grab active:cursor-grabbing transition-colors">
                    <GripVertical size={14} />
                </div>
            )}
            <div className="flex items-center gap-2">
                <span className="flex items-center gap-1 font-mono text-[10px] text-slate-400 font-black uppercase tracking-tighter">
                    <Hash size={10} className="opacity-40" /> {data.id.split('-')[1]}
                </span>
                {data.isReturned && !isMinimized && (
                     <span className="text-[9px] bg-red-600 text-white px-2 py-0.5 rounded-md font-black tracking-widest flex items-center gap-1.5 shadow-lg shadow-red-100 uppercase">
                        <AlertCircle size={10}/> REVISIÓN
                     </span>
                )}
            </div>
        </div>

        <div className="flex items-center gap-2">
           {!isMinimized && (
             <span className={`text-[9px] font-black px-2.5 py-1 rounded-lg border shadow-sm transition-all uppercase tracking-widest ${PRIORITY_STYLES[data.priority]}`}>
               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1.5 text-slate-300 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-all"
           >
               {isMinimized ? <ChevronDown size={16}/> : <ChevronUp size={16}/>}
           </button>
        </div>
      </div>

      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-5 pr-12' : 'flex flex-col'}`}>
        <h3 className={`font-black text-slate-800 leading-snug tracking-tight group-hover:text-indigo-600 transition-colors 
            ${isMinimized ? 'text-xs truncate flex-1 uppercase' : 'text-[15px] mb-3 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/80 p-4 rounded-xl border border-slate-100/50 mb-4 overflow-hidden shadow-inner">
                <p className="text-xs text-slate-500 leading-relaxed line-clamp-2 font-medium italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {!isMinimized ? (
          <div className="mt-auto pt-4 border-t border-slate-100/80 flex flex-col gap-3 shrink-0">
             <div className="flex items-center justify-between">
                <div className="flex flex-col gap-1">
                    <div className="flex items-center gap-2 text-[10px] font-black text-indigo-500 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded-md w-fit">
                        <MapPin size={11} strokeWidth={3} /> {data.area}
                    </div>
                    <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase tracking-tighter max-w-[160px]">
                        <Building2 size={11} className="opacity-40" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex flex-col items-end gap-1.5">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-2 bg-indigo-600 text-white px-3 py-1 rounded-xl text-[9px] font-black border border-indigo-700 shadow-xl shadow-indigo-100" title="Responsable Técnico">
                            <UserIcon size={10} strokeWidth={3} />
                            <span className="truncate max-w-[80px] uppercase">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-2 text-slate-400 font-mono text-[10px] font-black bg-slate-50 px-2.5 py-1 rounded-lg border border-slate-100">
                            <Clock size={11} strokeWidth={3} />
                            {new Date(data.createdAt).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </div>
                    )}
                </div>
             </div>
          </div>
      ) : (
          <div className="absolute right-12 top-1/2 -translate-y-1/2 flex items-center gap-3 pointer-events-none opacity-40">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{data.area}</span>
              <div className={`w-2 h-2 rounded-full ${data.status === Status.FINALIZADO ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]' : 'bg-slate-300'}`}></div>
          </div>
      )}
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, ViewMode, TransitionRule } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  initError: string | null;
  activeRole: UserRole | null;
  viewMode: ViewMode;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  switchHybridRole: () => void;
  setViewMode: (mode: ViewMode) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
  isActionable: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

const WORKFLOW_MATRIX: TransitionRule[] = [
  { from: Status.RECIBIDO, to: Status.DERIVACION, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.DERIVACION, to: Status.EJECUCION, allowedRoles: [UserRole.HEAD, UserRole.SUPERADMIN], requiresAnalyst: true, checkAreaJurisdiction: true },
  { from: Status.EJECUCION, to: Status.FINALIZADO, allowedRoles: [UserRole.ANALYST, UserRole.HEAD, UserRole.ADMIN, UserRole.SUPERADMIN], checkAreaJurisdiction: true },
  { from: Status.RECIBIDO, to: Status.FINALIZADO, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.DERIVACION, to: Status.FINALIZADO, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.FINALIZADO, to: Status.RECIBIDO, allowedRoles: [UserRole.SUPERADMIN] }
];

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [initError, setInitError] = useState<string | null>(null);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
        setIsLoading(false);
      } catch (error) {
        console.error("CRITICAL: SISREQ Storage Layer Failure", error);
        setInitError("No se pudo conectar con la base de datos local. Verifique los permisos de su navegador.");
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    setGlobalFilterArea(user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN ? 'ALL' : (user.area as Area));
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setViewMode('work');
  };

  const switchHybridRole = () => {
    if (!currentUser || currentUser.role !== UserRole.ADMIN || !currentUser.area) return;

    // Cambio atómico para evitar inconsistencia de renderizado
    const isNowHead = activeRole === UserRole.ADMIN;
    setActiveRole(isNowHead ? UserRole.HEAD : UserRole.ADMIN);
    setGlobalFilterArea(isNowHead ? (currentUser.area as Area) : 'ALL');
  };

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;
    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no válida.' };
    if (req.status === target) return { allowed: true };

    const rule = WORKFLOW_MATRIX.find(r => r.from === req.status && r.to === target);

    if (!rule) {
        if (target === Status.RECIBIDO && req.status !== Status.FINALIZADO) {
            const hasPower = [UserRole.ADMIN, UserRole.SUPERADMIN, UserRole.HEAD].includes(activeRole);
            return hasPower ? { allowed: true } : { allowed: false, reason: 'No tiene facultades para devolver a central.' };
        }
        return { allowed: false, reason: 'Fase de flujo no permitida institucionalmente.' };
    }

    if (!rule.allowedRoles.includes(activeRole)) {
        return { allowed: false, reason: `Su rol (${activeRole}) no está autorizado para esta fase.` };
    }

    if (rule.checkAreaJurisdiction && ![UserRole.SUPERADMIN, UserRole.ADMIN].includes(activeRole)) {
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Operación fuera de su jurisdicción técnica.' };
    }

    if (rule.requiresAnalyst && !req.assignedAnalyst) {
        return { allowed: false, reason: 'Debe asignar un Responsable Técnico antes de iniciar ejecución.' };
    }

    return { allowed: true };
  }, [currentUser, activeRole]);

  const isActionable = useCallback((req: RequestCard): boolean => {
    if (!activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN) return true;

    const possibleTargets = Object.values(Status).filter(s => s !== req.status);
    return possibleTargets.some(target => canUserTransition(req, target).allowed);
  }, [activeRole, canUserTransition]);

  // --- OPERACIONES CON INTEGRIDAD DISK-FIRST ---

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser || ![UserRole.ADMIN, UserRole.SUPERADMIN].includes(activeRole!)) {
        throw new Error("No tiene permisos para registrar nuevos requerimientos.");
    }

    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title: title.trim(),
      detail: detail.trim(),
      area,
      status: Status.RECIBIDO,
      priority,
      requester: requester.trim(),
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro oficial en sistema central',
        actor: currentUser.name,
        role: activeRole!
      }]
    };

    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const validation = canUserTransition(req, newStatus);
    if (!validation.allowed) throw new Error(validation.reason);

    const now = new Date().toISOString();
    const isReturning = newStatus === Status.RECIBIDO;

    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      assignedAnalyst: isReturning ? undefined : req.assignedAnalyst,
      isReturned: isReturning ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `WORKFLOW: Transición de fase hacia [${newStatus.toUpperCase()}]`,
        actor: currentUser!.name,
        role: activeRole!
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;

    if (![UserRole.ADMIN, UserRole.SUPERADMIN, UserRole.HEAD].includes(activeRole!)) {
        throw new Error("No tiene facultades para retornar el expediente.");
    }

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN TÉCNICA: ${reason}`,
        actor: currentUser!.name,
        role: activeRole!
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;

    if (![UserRole.HEAD, UserRole.SUPERADMIN, UserRole.ADMIN].includes(activeRole!)) {
        throw new Error("Solo las jefaturas pueden asignar responsables técnicos.");
    }

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN OPERATIVA: Se designa a [${analystName.toUpperCase()}] como responsable.`,
        actor: currentUser!.name,
        role: activeRole!
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: message.trim(),
        actor: currentUser!.name,
        role: activeRole!
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;

    if (![UserRole.ADMIN, UserRole.SUPERADMIN].includes(activeRole!)) {
        throw new Error("Solo el personal administrativo puede editar los alcances del requerimiento.");
    }

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title: title.trim(),
      detail: detail.trim(),
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: 'MODIFICACIÓN: Actualización de metadatos del expediente.',
        actor: currentUser!.name,
        role: activeRole!
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) {
        throw new Error("Operación restringida a Auditoría Master (SuperAdmin).");
    }
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    if (activeRole !== UserRole.SUPERADMIN) throw new Error("Acceso denegado.");

    const newUser: User = {
      id: genId('U'),
      name: name.trim(),
      email: email.trim(),
      role,
      area,
      password: pass,
      status: 'ACTIVE',
      joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    if (activeRole !== UserRole.SUPERADMIN && currentUser?.id !== u.id) throw new Error("Acceso denegado.");

    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, initError, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, switchHybridRole, setViewMode, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest, isActionable
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

