  if (initError) {
      return (
        <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 p-6 text-center">
            <div className="bg-red-50 p-6 rounded-[2.5rem] border border-red-100 max-w-md shadow-xl">
