import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, Area, UserRole } from '../types';
import { Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown, LayoutGrid, ShieldAlert } from 'lucide-react';

export const Board: React.FC = () => {
  const { requests, updateStatus, globalFilterArea, setGlobalFilterArea, activeRole, canUserSeeRequest, canUserTransition } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [errorToast, setErrorToast] = useState<string | null>(null);

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      if (!canUserSeeRequest(req)) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, canUserSeeRequest]);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');

    const req = requests.find(r => r.id === requestId);
    if (!req) return;

    if (req.status === targetStatus) return;

    try {
        await updateStatus(requestId, targetStatus);
    } catch (err: any) {
        setErrorToast(err.message);
        setTimeout(() => setErrorToast(null), 4000);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja Central', status: Status.RECIBIDO, icon: <Inbox size={18} />, color: 'indigo' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={18} />, color: 'orange' },
    { title: 'Ejecución Técnica', status: Status.EJECUCION, icon: <PlayCircle size={18} />, color: 'amber' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={18} />, color: 'emerald' }
  ];

  return (
    <div className="flex flex-col h-full relative">
      {/* Operative Error Toast */}
      {errorToast && (
          <div className="absolute top-24 left-1/2 -translate-x-1/2 z-[100] bg-red-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 duration-300">
              <ShieldAlert size={20} />
              <span className="text-xs font-black uppercase tracking-widest">{errorToast}</span>
          </div>
      )}

      <div className="px-8 py-6 flex flex-col md:flex-row md:items-center justify-between gap-6 bg-white/50 backdrop-blur-sm border-b border-slate-200/50 shadow-sm z-20">
          <div className="flex items-center gap-6">
             <div className="flex flex-col">
                 <div className="flex items-center gap-3 mb-1.5">
                    <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                    <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] leading-none">
                        Tablero de Operaciones
                    </h2>
                 </div>
                 <div className="flex items-center gap-4">
                    <span className="text-2xl font-black text-slate-900 tracking-tighter">Ciclo de Vida</span>
                    <span className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-[10px] font-black border border-indigo-100 shadow-sm">
                        {filteredRequests.length} EXPEDIENTES
                    </span>
                 </div>
             </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative group">
                <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar por ID, Solicitante o Responsable..." 
                    className="w-full min-w-[350px] pl-12 pr-6 py-3 text-sm font-bold bg-white border-2 border-slate-100 rounded-2xl focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-300 shadow-inner"
                />
             </div>

             {(activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                <div className="relative">
                    <LayoutGrid size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="pl-12 pr-10 py-3 text-xs font-black bg-white border-2 border-slate-100 rounded-2xl appearance-none cursor-pointer outline-none focus:border-indigo-500 transition-all uppercase tracking-[0.15em] text-slate-600 shadow-sm"
                    >
                        <option value="ALL">Jurisdicción Global</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a.toUpperCase()}</option>)}
                    </select>
                    <ChevronDown size={16} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
          <div className="h-full flex px-8 py-10 gap-10 min-w-[1400px]">
              {COLUMNS.map((col) => {
                  if (col.status === Status.RECIBIDO && activeRole !== UserRole.ADMIN && activeRole !== UserRole.SUPERADMIN) return null;

                  const items = filteredRequests.filter(r => r.status === col.status);
                  const isDragActive = dragOverColumn === col.status;

                  return (
                      <div 
                          key={col.status} 
                          className={`flex-1 flex flex-col min-w-[320px] max-w-[400px] rounded-[3rem] transition-all duration-300 ${isDragActive ? 'bg-indigo-50/70 ring-2 ring-indigo-200 ring-dashed scale-[1.02]' : 'bg-transparent'}`} 
                          onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }} 
                          onDragLeave={() => setDragOverColumn(null)} 
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          <div className="flex items-center justify-between px-8 py-5 bg-white border border-slate-100 rounded-3xl mb-8 shadow-sm ring-1 ring-black/5">
                              <div className="flex items-center gap-4">
                                  <div className={`p-3 rounded-2xl bg-${col.color}-50 text-${col.color}-600 shadow-inner`}>{col.icon}</div>
                                  <span className={`text-[11px] font-black uppercase tracking-[0.2em] text-slate-700`}>{col.title}</span>
                              </div>
                              <span className="bg-slate-100 text-slate-500 px-3 py-1.5 rounded-xl text-[10px] font-black border border-slate-200">{items.length}</span>
                          </div>

                          <div className="flex-1 overflow-y-auto px-2 pb-24 custom-scrollbar space-y-6">
                              {items.map(req => <RequestCard key={req.id} data={req} />)}
                              {items.length === 0 && (
                                  <div className="flex flex-col items-center justify-center h-48 border-4 border-dashed border-slate-200/50 rounded-[3rem] text-slate-300">
                                      <div className="mb-4 opacity-20 transform scale-150">{col.icon}</div>
                                      <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">Fase sin pendientes</p>
                                  </div>
                              )}
                          </div>
                      </div>
                  )
              })}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, PRIORITY_STYLES } from '../constants';
import { UserRole, Status } from '../types';
