};

import React, { useState, useRef, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, User } from '../types';
import { LayoutDashboard, User as UserIcon, Shield, Briefcase, KeyRound, LogIn, ChevronDown, Check, Sparkles, AlertCircle } from 'lucide-react';

const getRoleLabel = (role: UserRole) => {
  switch (role) {
      case UserRole.SUPERADMIN: return 'Control Maestro';
      case UserRole.ADMIN: return 'Administración Central';
      case UserRole.HEAD: return 'Jefaturas de Área';
      default: return 'Cuerpo Analista';
  }
};

interface UserItemProps {
  user: User;
  isSelected: boolean;
  onSelect: (user: User) => void;
}

const UserItem: React.FC<UserItemProps> = ({ user, isSelected, onSelect }) => (
    <button 
      type="button"
      onClick={() => onSelect(user)}
      className="w-full flex items-center gap-4 p-4 hover:bg-indigo-50/50 transition-all text-left group border-b border-slate-50 last:border-0"
    >
      <div className={`w-11 h-11 rounded-xl flex items-center justify-center font-black text-[11px] transition-all shadow-sm group-hover:scale-105 shrink-0 ${
          user.role === UserRole.SUPERADMIN ? 'bg-slate-900 text-white' :
          user.role === UserRole.ADMIN ? 'bg-red-50 text-red-600 group-hover:bg-red-100' :
          user.role === UserRole.HEAD ? 'bg-indigo-50 text-indigo-600 group-hover:bg-indigo-100' :
          'bg-slate-100 text-slate-500 group-hover:bg-slate-200'
      }`}>
          {user.name.substring(0, 2).toUpperCase()}
      </div>
      <div className="flex-1 min-w-0 flex flex-col justify-center">
          <div className="text-[13px] font-black text-slate-800 group-hover:text-indigo-600 truncate uppercase tracking-tight leading-none mb-1.5">{user.name}</div>
          <div className="text-[9px] text-slate-400 font-black uppercase tracking-widest truncate leading-none">{user.area || getRoleLabel(user.role)}</div>
      </div>
      {isSelected && <div className="bg-indigo-600 p-1.5 rounded-full text-white shadow-xl shadow-indigo-200 shrink-0"><Check size={14} strokeWidth={3}/></div>}
    </button>
);

export const LoginPage: React.FC = () => {
  const { login, users } = useSisreq();
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const superAdminUsers = users.filter(u => u.role === UserRole.SUPERADMIN);
  const adminUsers = users.filter(u => u.role === UserRole.ADMIN);
  const headUsers = users.filter(u => u.role === UserRole.HEAD);
  const analystUsers = users.filter(u => u.role === UserRole.ANALYST);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUser) return;

    // Validación de seguridad SISREQ: Primero contraseña específica, luego master demo
    if (password === selectedUser.password || (selectedUser.password === undefined && password === '123') || password === '1234') {
        login(selectedUser);
    } else {
        setError('Acceso denegado: La credencial ingresada es incorrecta.');
        setPassword('');
    }
  };

  const handleSelectUser = (user: User) => {
      setSelectedUser(user);
      setIsDropdownOpen(false);
      setPassword('');
      setError('');
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col items-center justify-center p-6">
        <div className="mb-12 text-center animate-in fade-in slide-in-from-bottom-6 duration-700">
            <div className="inline-flex items-center gap-6 mb-5 bg-white p-5 rounded-[2.5rem] shadow-[0_25px_50px_-15px_rgba(0,0,0,0.12)] border border-slate-100">
                <div className="bg-indigo-600 p-4 rounded-[1.5rem] shadow-2xl shadow-indigo-200">
                    <LayoutDashboard className="text-white" size={32} strokeWidth={2.5}/>
                </div>
                <div className="text-left pr-6">
                    <h1 className="text-4xl font-black tracking-tighter text-slate-900 leading-none">SISREQ</h1>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.3em] mt-2.5">Workflow de Requerimientos</p>
                </div>
            </div>
        </div>

        <div className="bg-white w-full max-w-md rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.18)] border border-slate-200 p-12 animate-in zoom-in-95 duration-500 relative overflow-visible">
            <div className="mb-10 flex items-center gap-4">
                <div className="bg-indigo-50 p-3 rounded-2xl text-indigo-600 shadow-sm"><Sparkles size={20}/></div>
                <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase leading-none">Control de Acceso</h2>
            </div>

            <form onSubmit={handleLogin} className="space-y-8">
                <div className="space-y-3" ref={dropdownRef}>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2.5 mb-2 ml-1 leading-none"><UserIcon size={12} className="text-indigo-500"/> Identidad Institucional</label>
                    <div className="relative">
                        <button
                            type="button"
                            onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                            className={`w-full h-[64px] bg-slate-50 border-2 ${isDropdownOpen ? 'border-indigo-600 bg-white ring-[12px] ring-indigo-500/5' : 'border-slate-100 hover:border-slate-200 hover:bg-slate-100/50'} rounded-2xl px-5 flex items-center justify-between transition-all outline-none shadow-inner`}
                        >
                            {selectedUser ? (
                                <div className="flex items-center gap-4 min-w-0">
                                    <div className={`w-9 h-9 rounded-xl flex items-center justify-center font-black text-[10px] shrink-0 shadow-sm ${
                                        selectedUser.role === UserRole.SUPERADMIN ? 'bg-slate-900 text-white' :
                                        selectedUser.role === UserRole.ADMIN ? 'bg-red-500 text-white' :
                                        selectedUser.role === UserRole.HEAD ? 'bg-indigo-600 text-white' :
                                        'bg-slate-400 text-white'
                                    }`}>
                                        {selectedUser.name.substring(0, 2).toUpperCase()}
                                    </div>
                                    <div className="text-left min-w-0 flex flex-col justify-center">
                                        <div className="text-[14px] font-black text-slate-900 truncate uppercase tracking-tight leading-none mb-1">{selectedUser.name}</div>
                                        <div className="text-[9px] text-slate-500 font-black uppercase tracking-widest truncate leading-none">{selectedUser.area || getRoleLabel(selectedUser.role)}</div>
                                    </div>
                                </div>
                            ) : (
                                <span className="text-slate-400 text-[11px] font-black uppercase tracking-widest leading-none">Seleccione perfil operativo</span>
                            )}
                            <ChevronDown size={20} className={`text-slate-400 transition-transform shrink-0 ${isDropdownOpen ? 'rotate-180 text-indigo-600' : ''}`}/>
                        </button>

                        {isDropdownOpen && (
                            <div className="absolute top-full left-0 right-0 mt-4 bg-white rounded-[2rem] shadow-[0_30px_70px_-15px_rgba(0,0,0,0.3)] border border-slate-200 z-50 max-h-80 overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-top-3">
                                {superAdminUsers.length > 0 && (
                                    <>
                                        <div className="sticky top-0 bg-slate-50 px-5 py-3 border-b border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-[0.25em] z-10 flex items-center gap-3">
                                            <Shield size={12} /> Control Central Auditoría
                                        </div>
                                        {superAdminUsers.map(u => (
                                            <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={handleSelectUser} />
                                        ))}
                                    </>
                                )}
                                <div className="sticky top-0 bg-slate-50 px-5 py-3 border-y border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-[0.25em] z-10 flex items-center gap-3">
                                    <Shield size={12} /> Administración Central
                                </div>
                                {adminUsers.map(u => (
                                    <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={handleSelectUser} />
                                ))}
                                <div className="sticky top-0 bg-slate-50 px-5 py-3 border-y border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-[0.25em] z-10 flex items-center gap-3">
                                    <Briefcase size={12} /> Jefaturas de Área
                                </div>
                                {headUsers.map(u => (
                                    <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={handleSelectUser} />
                                ))}
                                <div className="sticky top-0 bg-slate-50 px-5 py-3 border-y border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-[0.25em] z-10 flex items-center gap-3">
                                    <UserIcon size={12} /> Personal Analista
                                </div>
                                {analystUsers.map(u => (
                                    <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={handleSelectUser} />
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {selectedUser && (
                    <div className="space-y-6 animate-in slide-in-from-top-4 fade-in duration-400">
                        <div className="space-y-3">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2.5 mb-2 ml-1 leading-none"><KeyRound size={12} className="text-indigo-500"/> Firma Electrónica / Clave</label>
                            <input 
                                type="password" 
                                autoFocus
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full h-[72px] bg-slate-50 border-2 border-slate-100 rounded-2xl focus:ring-[12px] focus:ring-indigo-500/5 focus:border-indigo-600 focus:bg-white outline-none transition-all font-black text-center text-xl tracking-[0.6em] shadow-inner"
                                placeholder="••••"
                            />
                        </div>

                        {error && (
                            <div className="bg-red-50 text-red-600 p-5 rounded-2xl text-[11px] font-black uppercase tracking-widest flex items-center gap-4 animate-in shake border border-red-100 shadow-sm leading-none">
                                <AlertCircle size={18} strokeWidth={3} className="shrink-0"/> {error}
                            </div>
                        )}

                        <button 
                            type="submit"
                            className="w-full h-[72px] bg-slate-900 hover:bg-slate-800 text-white font-black rounded-2xl shadow-2xl shadow-slate-300 hover:-translate-y-1 transition-all active:scale-95 flex items-center justify-center gap-4 uppercase text-[11px] tracking-[0.25em] border border-slate-900"
                        >
                            <LogIn size={22} strokeWidth={2.5} className="shrink-0"/> 
                            <span className="leading-none">Validar Credenciales</span>
                        </button>
                    </div>
                )}
            </form>

            <div className="mt-12 text-center">
                <div className="inline-block px-6 py-3.5 bg-slate-50 rounded-full text-[10px] font-black text-slate-400 uppercase tracking-widest border border-slate-100 shadow-inner leading-none">
                    Modo demo: <span className="text-indigo-600">123</span> o <span className="text-indigo-600">1234</span>
                </div>
            </div>
        </div>
    </div>
  );
};

