                                    <Shield size={12} strokeWidth={3}/> Gestión Central
                                </div>
                                {adminUsers.map(u => (
                                    <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={handleSelectUser} />
                                ))}
                                <div className="sticky top-0 bg-slate-50 px-6 py-4 border-y border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-[0.3em] z-10 flex items-center gap-3">
                                    <Briefcase size={12} strokeWidth={3}/> Jefaturas Operativas
                                </div>
                                {headUsers.map(u => (
                                    <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={handleSelectUser} />
                                ))}
                                <div className="sticky top-0 bg-slate-50 px-6 py-4 border-y border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-[0.3em] z-10 flex items-center gap-3">
                                    <UserIcon size={12} strokeWidth={3}/> Cuerpo Analista
                                </div>
                                {analystUsers.map(u => (
                                    <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={handleSelectUser} />
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {selectedUser && (
                    <div className="space-y-8 animate-in slide-in-from-top-6 fade-in duration-500">
                        <div className="space-y-4">
