                            </label>
                            <input 
                                type="password" 
                                autoFocus
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full h-[76px] bg-[#F8FAFC] border-2 border-slate-100 rounded-[1.25rem] focus:ring-[15px] focus:ring-indigo-500/5 focus:border-indigo-600 focus:bg-white outline-none transition-all font-black text-center text-2xl tracking-[0.8em] shadow-inner placeholder:tracking-normal placeholder:text-slate-200"
                                placeholder="••••"
