                            </div>
                        )}

                        <button 
                            type="submit"
                            className="w-full h-[76px] bg-[#1E293B] hover:bg-[#0F172A] text-white font-black rounded-[1.25rem] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.25)] hover:-translate-y-1 transition-all active:scale-95 flex items-center justify-center gap-4 uppercase text-[11px] tracking-[0.3em] border border-[#1E293B]"
