                <div className="inline-block px-8 py-4 bg-[#F8FAFC] rounded-full text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border border-slate-100 shadow-inner leading-none">
                    Modo demo: <span className="text-indigo-600 mx-1">123</span> o <span className="text-indigo-600 mx-1">1234</span>
                </div>
            </div>
        </div>
    </div>
  );
};
